((SELECT ID_SECCION FROM INS_SECCION WHERE CODIGO = 'A'), 'Distribucion de las Areas - Art. 8 y 9', 'Segun corresponda, cuenta con las areas claramente definidas de: almacenamiento y conservacion, Preparacion, Consumo, Servicios sanitarios', 1, 'N', 10);
