INSERT INTO INS_ITEM (ID_SECCION, ARTICULO, DESCRIPCION, PUNTAJE, ES_CRITICO, ORDEN) VALUES
((SELECT ID_SECCION FROM INS_SECCION WHERE CODIGO = 'D'), 'De los residuos solidos y liquidos - Art. 63', 'Se destina un area aislada y protegida contra plagas para el almacenamiento temporal de recipientes con residuos solidos y se encuentra en buen estado de conservacion e higiene.', 1, 'N', 20);
INSERT INTO INS_ITEM (ID_SECCION, ARTICULO, DESCRIPCION, PUNTAJE, ES_CRITICO, ORDEN) VALUES
((SELECT ID_SECCION FROM INS_SECCION WHERE CODIGO = 'E'), 'Art. 4 carne manipulador', 'El personal cuenta con el carne de manipulador de alimentos vigente', 1, 'N', 1);
INSERT INTO INS_ITEM (ID_SECCION, ARTICULO, DESCRIPCION, PUNTAJE, ES_CRITICO, ORDEN) VALUES
((SELECT ID_SECCION FROM INS_SECCION WHERE CODIGO = 'E'), 'Salud del personal - Art. 57', 'Se observa al personal libre de lesiones externas como heridas abiertas o infectadas, infecciones cutaneas o llagas', 2, 'N', 2);
INSERT INTO INS_ITEM (ID_SECCION, ARTICULO, DESCRIPCION, PUNTAJE, ES_CRITICO, ORDEN) VALUES
((SELECT ID_SECCION FROM INS_SECCION WHERE CODIGO = 'E'), 'Salud del personal - Art. 57', 'El propietario o administrador toma medidas para evitar que el personal enfermo trabaje en zonas de manipulacion de alimentos.', 3, 'N', 3);
INSERT INTO INS_ITEM (ID_SECCION, ARTICULO, DESCRIPCION, PUNTAJE, ES_CRITICO, ORDEN) VALUES
((SELECT ID_SECCION FROM INS_SECCION WHERE CODIGO = 'E'), 'Higiene y habitos del personal - Art. 58', 'Los empleados mantienen las unas limpias, recortadas, sin esmalte, no utilizan maquillaje y no portan joyas durante las horas laborales y se observan buenos habitos de higiene. (En su area de trabajo: no comen, no fuman, no mascan chicle entre otros). Esto aplica para el area de preparacion de alimentos.', 2, 'N', 4);
INSERT INTO INS_ITEM (ID_SECCION, ARTICULO, DESCRIPCION, PUNTAJE, ES_CRITICO, ORDEN) VALUES
((SELECT ID_SECCION FROM INS_SECCION WHERE CODIGO = 'E'), 'Higiene y habitos del personal - Art. 58', 'El personal encargado de caja que manipula dinero no debe participar en actividades relacionadas con la manipulacion de alimentos durante el tiempo que realiza esta funcion.', 1, 'N', 5);
INSERT INTO INS_ITEM (ID_SECCION, ARTICULO, DESCRIPCION, PUNTAJE, ES_CRITICO, ORDEN) VALUES
